import com.example.demo.application.commands.CreateCommand;
import com.example.demo.domain.Note;
import com.example.demo.domain.TimeOrderedUuid;
import com.example.demo.domain.events.CreatedEvent;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public final class JdbcCreateCommand implements CreateCommand {

    private final JdbcClient jdbc;
    private final ApplicationEventPublisher events;

    public JdbcCreateCommand(JdbcClient jdbc, ApplicationEventPublisher events) {
        this.jdbc = jdbc;
        this.events = events;
    }

    @Override
    public Note execute(CreateCommand.Input input) {
        JdbcClient.StatementSpec statement = jdbc.sql("insert into notes (id, title, status) values (:id, :title, :status) returning id, title, status");
        statement = statement.param("id", TimeOrderedUuid.next());
        statement = statement.param("title", input.title());
        statement = statement.param("status", input.status());
        var result = statement.query(Note.class).single();
        events.publishEvent(new CreatedEvent(result.id(), result.title()));
        return result;
    }
}
